import React, { useState, useEffect } from 'react';
import { ApiScheduleItem, SongOfTheWeek, SongRequestRecord, ListeningStats } from '../types';
import ShareModal from './ShareModal';
import { getSongOfTheWeek } from '../services/geminiService';

interface ScheduleProps {
  schedule: ApiScheduleItem[];
  loading: boolean;
  error: string | null;
  favoriteShows: number[];
  onToggleFavorite: (showId: number) => void;
  songRequests: SongRequestRecord[];
  listeningStats: ListeningStats;
}

const StarIcon = ({ filled }: { filled: boolean }) => (
  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5} fill={filled ? "currentColor" : "none"}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M11.48 3.499a.562.562 0 011.04 0l2.125 5.111a.563.563 0 00.475.345l5.518.442c.499.04.701.663.321.988l-4.204 3.602a.563.563 0 00-.182.557l1.285 5.385a.562.562 0 01-.84.61l-4.725-2.885a.563.563 0 00-.586 0L6.982 20.54a.562.562 0 01-.84-.61l1.285-5.386a.562.562 0 00-.182-.557l-4.204-3.602a.563.563 0 01.321-.988l5.518-.442a.563.563 0 00.475-.345L11.48 3.5z" />
  </svg>
);

const ShareIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
        <path strokeLinecap="round" strokeLinejoin="round" d="M8.684 13.542l-1.12 1.12a5 5 0 007.07 7.07l4.243-4.242a5 5 0 00-7.07-7.07l-1.12 1.12M15.316 10.458l1.12-1.12a5 5 0 00-7.07-7.07l-4.243 4.242a5 5 0 007.07 7.07l1.12-1.12" />
    </svg>
);


const Schedule: React.FC<ScheduleProps> = ({ schedule, loading, error, favoriteShows, onToggleFavorite, songRequests, listeningStats }) => {
  const [showToShare, setShowToShare] = useState<ApiScheduleItem | null>(null);
  const [songOfTheWeek, setSongOfTheWeek] = useState<SongOfTheWeek | null>(null);
  const [isSotwLoading, setIsSotwLoading] = useState(true);
  const [sotwError, setSotwError] = useState<string | null>(null);
  const [showOnlySotw, setShowOnlySotw] = useState(false);

  useEffect(() => {
    const fetchSotw = async () => {
      const SOTW_CACHE_KEY = 'nam-radio-sotw-cache';
      const CACHE_DURATION = 4 * 60 * 60 * 1000; // 4 hours

      try {
        const cachedItem = sessionStorage.getItem(SOTW_CACHE_KEY);
        if (cachedItem) {
          const { data, timestamp } = JSON.parse(cachedItem);
          if (Date.now() - timestamp < CACHE_DURATION) {
            setSongOfTheWeek(data);
            setIsSotwLoading(false);
            return;
          }
        }
      } catch (e) { console.error("Failed to read SOTW from cache", e); }

      setIsSotwLoading(true);
      setSotwError(null);
      try {
        const data = await getSongOfTheWeek(songRequests, listeningStats);
        setSongOfTheWeek(data);
        sessionStorage.setItem(SOTW_CACHE_KEY, JSON.stringify({ data, timestamp: Date.now() }));
      } catch (err: any) {
        setSotwError(err.message);
      } finally {
        setIsSotwLoading(false);
      }
    };

    fetchSotw();
  }, [songRequests, listeningStats]);

  const groupShowsByDay = (shows: ApiScheduleItem[]) => {
    return shows.reduce((acc, show) => {
      const showDate = new Date(show.start);
      // Group by a simpler key to avoid timezone issues with toLocaleDateString
      const dayKey = new Date(showDate.getFullYear(), showDate.getMonth(), showDate.getDate()).toISOString();

      if (!acc[dayKey]) {
        acc[dayKey] = [];
      }
      acc[dayKey].push(show);
      return acc;
    }, {} as Record<string, ApiScheduleItem[]>);
  };

  const groupedSchedule = groupShowsByDay(schedule);

  const formatTime = (dateString: string) => {
    return new Date(dateString).toLocaleTimeString('en-US', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    });
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
    });
  }

  const renderContent = () => {
    if (loading) {
       return (
        <div className="flex justify-center items-center h-48">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-300"></div>
        </div>
      );
    }

    if (error) {
       return <p className="text-center text-red-400 py-4">{error}</p>;
    }

    if (schedule.length === 0 || Object.keys(groupedSchedule).length === 0) {
      return <p className="text-center text-slate-500 py-4">Schedule is currently unavailable.</p>;
    }

    return (
      <div className="space-y-8">
        {Object.entries(groupedSchedule).sort((a,b) => new Date(a[0]).getTime() - new Date(b[0]).getTime()).map(([dayKey, shows]) => (
          <div key={dayKey}>
            <h3 className="text-xl font-bold text-amber-300 mb-4 border-b-2 border-amber-500/30 pb-2">{formatDate(dayKey)}</h3>
            <ul className="space-y-4">
              {shows.sort((a, b) => new Date(a.start).getTime() - new Date(b.start).getTime()).map((show) => {
                const isFavorite = favoriteShows.includes(show.id);
                return (
                  <li key={show.id} className={`p-4 bg-slate-800/50 rounded-lg flex flex-col sm:flex-row gap-4 items-start transition-all duration-300 ${isFavorite ? 'ring-2 ring-amber-400 bg-slate-800' : ''}`}>
                    <div className="flex-shrink-0 w-full sm:w-32 text-center sm:text-left bg-amber-500/20 p-2 rounded-md">
                      <p className="font-bold text-white text-md">{formatTime(show.start)}</p>
                      <p className="text-sm text-slate-400">to {formatTime(show.end)}</p>
                    </div>
                    <div className="flex-grow">
                      <h4 className="font-bold text-lg text-white">{show.name}</h4>
                      {show.description && <p className="text-sm text-slate-400 mt-1">{show.description}</p>}
                    </div>
                    <div className="flex-shrink-0 self-center flex items-center gap-2">
                      {show.is_now && (
                        <span className="px-3 py-1 text-xs font-semibold uppercase tracking-wider text-black bg-amber-300 rounded-full">
                          On Air
                        </span>
                      )}
                      <button
                        onClick={() => setShowToShare(show)}
                        className="p-2 rounded-full transition-colors text-slate-500 hover:text-amber-400 hover:bg-slate-700/50"
                        aria-label="Share show"
                      >
                        <ShareIcon />
                      </button>
                      <button
                        onClick={() => onToggleFavorite(show.id)}
                        className={`p-2 rounded-full transition-colors ${isFavorite ? 'text-amber-400' : 'text-slate-500 hover:text-amber-400 hover:bg-slate-700/50'}`}
                        aria-label={isFavorite ? 'Remove from favorites' : 'Add to favorites'}
                      >
                        <StarIcon filled={isFavorite} />
                      </button>
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>
        ))}
      </div>
    );
  };

  return (
    <section className="bg-slate-900/50 backdrop-blur-xl rounded-2xl p-6 md:p-8 shadow-lg border border-slate-700/50">
       <div className="flex flex-col sm:flex-row justify-between sm:items-center mb-6 gap-4">
        <h2 className="text-2xl font-bold tracking-wide text-amber-300">Weekly Schedule</h2>
        {songOfTheWeek && (
          <div className="flex items-center gap-2 flex-shrink-0">
              <label htmlFor="sotw-toggle" className="text-sm font-semibold text-slate-300 cursor-pointer">Show only Song of the Week</label>
              <button
                  id="sotw-toggle"
                  onClick={() => setShowOnlySotw(!showOnlySotw)}
                  className={`relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-slate-800 focus:ring-amber-400 ${showOnlySotw ? 'bg-amber-500' : 'bg-slate-700'}`}
                  aria-pressed={showOnlySotw}
              >
                  <span className={`inline-block w-4 h-4 transform bg-white rounded-full transition-transform ${showOnlySotw ? 'translate-x-6' : 'translate-x-1'}`} />
              </button>
          </div>
        )}
      </div>

      <div className="mb-8">
        <h3 className="text-xl font-bold text-white mb-4">Song of the Week</h3>
        {isSotwLoading && (
          <div className="flex items-center justify-center h-24 bg-slate-800/50 rounded-lg">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-amber-300"></div>
          </div>
        )}
        {sotwError && (
          <div className="p-4 bg-red-500/10 text-red-300 rounded-lg">
            <p className="font-semibold">Error fetching Song of the Week</p>
            <p className="text-sm">{sotwError}</p>
          </div>
        )}
        {songOfTheWeek && (
          <div className="bg-amber-500/10 p-4 rounded-lg border-l-4 border-amber-400 animate-fade-in">
            <p className="text-lg font-bold text-white">{songOfTheWeek.title}</p>
            <p className="text-md text-slate-300 mb-2">{songOfTheWeek.artist}</p>
            <div className="prose prose-sm prose-invert text-slate-400">
              <p className="italic">"{songOfTheWeek.description}"</p>
            </div>
          </div>
        )}
      </div>

      {!showOnlySotw && renderContent()}

      {showToShare && (
        <ShareModal 
          show={showToShare}
          onClose={() => setShowToShare(null)}
        />
      )}
    </section>
  );
};

export default Schedule;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { getRequestableSongs, submitSongRequest } from '../services/azuracastService';
// FIX: Import Song type for dedication payload.
import { RequestableSong, SongRequestRecord, Song } from '../types';

interface User {
  username: string;
}

interface SongRequestProps {
  currentUser: User | null;
  onAddSongRequest: (request: SongRequestRecord) => void;
  // FIX: Add a prop to handle dedications.
  onAddDedication: (dedication: { song: Song, to: string, message: string, from: string }) => void;
}

const SongRequest: React.FC<SongRequestProps> = ({ currentUser, onAddSongRequest, onAddDedication }) => {
  // FIX: Add tab state for switching between request and dedication.
  const [activeTab, setActiveTab] = useState<'request' | 'dedication'>('request');
  const [requestableSongs, setRequestableSongs] = useState<RequestableSong[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSong, setSelectedSong] = useState<RequestableSong | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [result, setResult] = useState<{success: boolean; message: string} | null>(null);
  const [timeLeft, setTimeLeft] = useState<number>(0);
  // FIX: Add state for dedication form data.
  const [dedicationData, setDedicationData] = useState({ to: '', message: '' });

  const userName = currentUser?.username || 'Guest';

  const resetForm = useCallback(() => {
    setSelectedSong(null);
    setSearchTerm('');
    setDedicationData({ to: '', message: '' });
    setResult(null);
  }, []);

  useEffect(() => {
    resetForm();
  }, [activeTab, resetForm]);

  // Cooldown logic
  useEffect(() => {
    const lastRequestKey = `nam-radio-live-last-request-${userName}`;
    const lastRequestTimeStr = localStorage.getItem(lastRequestKey);

    if (lastRequestTimeStr) {
      const lastRequestTime = new Date(lastRequestTimeStr).getTime();
      const now = new Date().getTime();
      const oneHour = 3600 * 1000;
      const timeSince = now - lastRequestTime;

      if (timeSince < oneHour) {
        setTimeLeft(Math.ceil((oneHour - timeSince) / 1000));
      }
    }

    const interval = setInterval(() => {
      setTimeLeft(prev => (prev > 0 ? prev - 1 : 0));
    }, 1000);

    return () => clearInterval(interval);
  }, [userName]);

  // Fetch requestable songs on mount
  useEffect(() => {
    const fetchSongs = async () => {
      setIsLoading(true);
      const songs = await getRequestableSongs();
      setRequestableSongs(songs);
      setIsLoading(false);
    };
    fetchSongs();
  }, []);

  const filteredSongs = useMemo(() => {
    if (!searchTerm) return [];
    const lowerCaseSearch = searchTerm.toLowerCase();
    return requestableSongs.filter(
      item =>
        item.song.title.toLowerCase().includes(lowerCaseSearch) ||
        item.song.artist.toLowerCase().includes(lowerCaseSearch)
    ).slice(0, 50);
  }, [searchTerm, requestableSongs]);

  const formatTimeLeft = (seconds: number) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}m ${remainingSeconds < 10 ? '0' : ''}${remainingSeconds}s`;
  };

  const handleSelectSong = (song: RequestableSong) => {
    setSelectedSong(song);
    setSearchTerm(`${song.song.title} - ${song.song.artist}`);
  };

  const handleDedicationChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setDedicationData({ ...dedicationData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setResult(null);

    if (timeLeft > 0) {
      setResult({ success: false, message: `You can make another request in ${formatTimeLeft(timeLeft)}.` });
      return;
    }

    if (!selectedSong) {
      setResult({ success: false, message: 'Please search for and select a song from the list.' });
      return;
    }

    if (activeTab === 'dedication' && (!dedicationData.to || !dedicationData.message)) {
      setResult({ success: false, message: 'Please fill out the dedication fields.' });
      return;
    }

    setIsSubmitting(true);
    const response = await submitSongRequest(selectedSong.request_id);

    if (response.success) {
      const newRequest: SongRequestRecord = {
        title: selectedSong.song.title,
        artist: selectedSong.song.artist,
        requestedAt: new Date().toISOString(),
      };
      onAddSongRequest(newRequest);

      if (activeTab === 'dedication' && currentUser) {
          onAddDedication({
              song: { title: selectedSong.song.title, artist: selectedSong.song.artist },
              to: dedicationData.to,
              message: dedicationData.message,
              from: currentUser.username,
          });
      }

      setResult({ success: true, message: activeTab === 'dedication' ? 'Your dedication has been sent!' : response.message });

      const lastRequestKey = `nam-radio-live-last-request-${userName}`;
      localStorage.setItem(lastRequestKey, new Date().toISOString());
      setTimeLeft(3600);
      resetForm();
    } else {
      setResult(response);
    }
    setIsSubmitting(false);
  };

  const TabButton: React.FC<{ type: 'request' | 'dedication'; children: React.ReactNode }> = ({ type, children }) => (
    <button
      type="button"
      onClick={() => setActiveTab(type)}
      className={`w-full text-center py-2 px-4 text-sm font-semibold rounded-t-lg transition-colors ${
        activeTab === type ? 'bg-slate-800/50 text-amber-300 border-b-2 border-amber-400' : 'text-slate-400 hover:text-white'
      }`}
    >
      {children}
    </button>
  );

  return (
    <section className="bg-slate-900/50 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-slate-700/50">
      <div className="flex border-b border-slate-700/50">
        <TabButton type="request">Request a Song</TabButton>
        <TabButton type="dedication">Make a Dedication</TabButton>
      </div>

      <div className="pt-6">
        {activeTab === 'dedication' && !currentUser && (
            <div className="text-center p-4 bg-amber-500/10 text-amber-300 rounded-lg">
                <p>Please log in to make a song dedication.</p>
            </div>
        )}
        <form onSubmit={handleSubmit} className={`space-y-4 ${activeTab === 'dedication' && !currentUser ? 'opacity-50 pointer-events-none' : ''}`}>
          <div>
            <label htmlFor="song-search" className="block text-sm font-medium text-slate-300 mb-1">1. Search for a song</label>
            <div className="relative">
              <input
                type="text"
                id="song-search"
                value={searchTerm}
                onChange={(e) => { setSearchTerm(e.target.value); setSelectedSong(null); }}
                className="w-full bg-slate-800 border border-slate-600 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-amber-400"
                placeholder="Start typing song or artist..."
                autoComplete="off"
                disabled={timeLeft > 0 || isLoading}
              />
              {isLoading && (
                <div className="absolute right-3 top-1/2 -translate-y-1/2">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-amber-300"></div>
                </div>
              )}
              {searchTerm && filteredSongs.length > 0 && (
                <ul className="absolute z-10 w-full mt-1 bg-slate-800 border border-slate-600 rounded-lg max-h-48 overflow-y-auto shadow-lg">
                  {filteredSongs.map(item => (
                    <li key={item.request_id}>
                      <button type="button" onClick={() => handleSelectSong(item)} className="w-full text-left px-4 py-2 text-white hover:bg-amber-500/20">
                        <span className="font-semibold block">{item.song.title}</span>
                        <span className="text-sm text-slate-400">{item.song.artist}</span>
                      </button>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          </div>
          {activeTab === 'dedication' && (
              <div className="space-y-4 animate-fade-in">
                  <div>
                    <label htmlFor="dedication-to" className="block text-sm font-medium text-slate-300 mb-1">2. To (Person's Name)</label>
                    <input type="text" id="dedication-to" name="to" value={dedicationData.to} onChange={handleDedicationChange} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-amber-400" required />
                  </div>
                  <div>
                    <label htmlFor="dedication-message" className="block text-sm font-medium text-slate-300 mb-1">3. Your Message</label>
                    <textarea id="dedication-message" name="message" value={dedicationData.message} onChange={handleDedicationChange} rows={3} className="w-full bg-slate-800 border border-slate-600 rounded-lg px-4 py-2 text-white focus:outline-none focus:ring-2 focus:ring-amber-400" required maxLength={150}></textarea>
                  </div>
              </div>
          )}
          <p className="text-xs text-slate-400">Requesting as: <span className="font-bold text-amber-300">{userName}</span></p>
          <button
            type="submit"
            disabled={isSubmitting || timeLeft > 0 || isLoading || !selectedSong}
            className="w-full bg-amber-500 hover:bg-amber-600 text-white font-bold py-2 px-4 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-amber-400 disabled:bg-slate-600 disabled:cursor-not-allowed"
          >
            {isSubmitting ? 'Sending...' : (timeLeft > 0 ? 'Request on Cooldown' : (activeTab === 'dedication' ? 'Send Dedication' : 'Send Request'))}
          </button>
        </form>
      </div>

      {result && (
        <p className={`mt-4 text-center p-3 rounded-lg text-sm ${result.success ? 'bg-green-500/10 text-green-300' : 'bg-red-500/10 text-red-400'}`}>
          {result.message}
        </p>
      )}

      {timeLeft > 0 && (
        <div className="mt-4 text-center text-amber-300 bg-amber-500/10 p-3 rounded-lg">
            <p className="text-sm">You can make another request in: <span className="font-bold tabular-nums">{formatTimeLeft(timeLeft)}</span></p>
        </div>
      )}

      {!isLoading && requestableSongs.length === 0 && (
        <p className="mt-4 text-center text-slate-400 bg-slate-800/50 p-3 rounded-lg text-sm">Song requests are currently disabled or unavailable.</p>
      )}
    </section>
  );
};

