  const handleGetFunFact = async () => {
    setIsLoadingFact(true);
    setFactError(null);
    setFunFact(null);
    try {
      const fact = await getSongFunFact(liveNowPlaying.song);
      setFunFact(fact);
    } catch (error) {
      setFactError("Could not fetch fun fact. Please try again later.");
    } finally {
      setIsLoadingFact(false);
    }
  };

