            </a>
            <a href={whatsappShareUrl} target="_blank" rel="noopener noreferrer" aria-label="Share on WhatsApp" className="p-3 bg-slate-800 hover:bg-slate-700 rounded-full transition-all text-white hover:scale-110">
              <WhatsAppIcon />
            </a>
          </div>
        </div>
      </div>
