import { AZURACAST_BASE_URL, AZURACAST_STATION_ID, WEEKLY_SCHEDULE, RECENTLY_PLAYED } from '../constants';
import { ApiScheduleItem, Song, RequestableSong, AzuraListeners, AzuraListenersReport, AzuraPerformanceReportItem, AzuraHistoryItem } from '../types';

// AzuraCast raw API types (for internal mapping)
interface AzuraNowPlayingSong {
  title: string;
  artist: string;
  art: string;
}

interface AzuraNowPlaying {
  listeners: AzuraListeners;
  now_playing: {
    song: AzuraNowPlayingSong;
    playlist?: string; // This is the show name or playlist name
    is_request: boolean;
    elapsed: number;
    duration: number;
  };
  live: {
      is_live: boolean;
      streamer_name: string;
      broadcast_title: string;
  };
  song_history: { song: AzuraNowPlayingSong }[];
}

interface AzuraScheduleItem {
    id: number;
    start_timestamp: number;
    end_timestamp: number;
    name: string;
    description: string;
    is_now: boolean;
}

// Function to map AzuraCast schedule to our app's type
const mapAzuraSchedule = (azuraSchedule: AzuraScheduleItem[]): ApiScheduleItem[] => {
    return azuraSchedule.map(azuraShow => {
        // Find a matching mock show to get an image URL, as AzuraCast API doesn't provide one.
        const mockShow = WEEKLY_SCHEDULE.find(mock => mock.name === azuraShow.name);
        return {
            id: azuraShow.id,
            start: new Date(azuraShow.start_timestamp * 1000).toISOString(),
            end: new Date(azuraShow.end_timestamp * 1000).toISOString(),
            name: azuraShow.name,
            description: azuraShow.description,
            is_now: azuraShow.is_now,
            imageUrl: mockShow?.imageUrl,
        };
    });
};

const getFallbackCurrentShow = (): string => {
    const now = new Date();
    const currentShow = WEEKLY_SCHEDULE.find(show => {
        const start = new Date(show.start);
        const end = new Date(show.end);
        return now >= start && now < end;
    });
    return currentShow ? currentShow.name : 'Nam Radio Live Auto-DJ';
};

/**
 * Fetches the live schedule from AzuraCast.
 */
export const getSchedule = async (): Promise<ApiScheduleItem[]> => {
    try {
        const response = await fetch(`${AZURACAST_BASE_URL}/api/station/${AZURACAST_STATION_ID}/schedule?_=${new Date().getTime()}`);
        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const data: AzuraScheduleItem[] = await response.json();
        return mapAzuraSchedule(data);
    } catch (error) {
        console.warn("Using fallback schedule due to API error:", error);
        return WEEKLY_SCHEDULE;
    }
};

/**
 * Fetches live "now playing" data from AzuraCast.
 */
export const getNowPlaying = async (): Promise<{ currentSong: Song, history: Song[], showName: string | null }> => {
    try {
        // Cache busting to ensure fresh data
        const response = await fetch(`${AZURACAST_BASE_URL}/api/nowplaying/${AZURACAST_STATION_ID}?_=${new Date().getTime()}`);
        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const data: AzuraNowPlaying = await response.json();

        const currentSong: Song = {
            title: data.now_playing.song.title,
            artist: data.now_playing.song.artist,
            artUrl: data.now_playing.song.art,
        };
        const history: Song[] = data.song_history.map(item => ({
            title: item.song.title,
            artist: item.song.artist,
            artUrl: item.song.art,
        }));

        // Determine show name: prioritizing live broadcast title, then streamer name, then playlist
        let showName = data.now_playing.playlist || null;
        if (data.live && data.live.is_live) {
            showName = data.live.broadcast_title || data.live.streamer_name || showName;
        }

        return { currentSong, history, showName };

    } catch (error) {
        console.warn("Using fallback now-playing data due to API error:", error);

        // Simulate a "live" song by rotating through recently played based on time
        const index = Math.floor(Date.now() / (3 * 60 * 1000)) % RECENTLY_PLAYED.length;
        const currentSong = RECENTLY_PLAYED[index];
        const history = RECENTLY_PLAYED.filter((_, i) => i !== index);
        const showName = getFallbackCurrentShow();

        return { currentSong, history, showName };
    }
};

/**
 * Fetches requestable songs from AzuraCast. Falls back to an empty list on failure.
 */
export const getRequestableSongs = async (): Promise<RequestableSong[]> => {
    try {
        const response = await fetch(`${AZURACAST_BASE_URL}/api/station/${AZURACAST_STATION_ID}/requests?_=${new Date().getTime()}`);
        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const data: RequestableSong[] = await response.json();
        return data;
    } catch (error) {
        console.warn("Failed to fetch requestable songs, returning empty list.", error);
        return [];
    }
};

/**
 * Submits a song request to the AzuraCast API.
 */
export const submitSongRequest = async (requestId: string): Promise<{ success: boolean; message: string; }> => {
    try {
        const url = `${AZURACAST_BASE_URL}/api/station/${AZURACAST_STATION_ID}/request/${requestId}`;
        const response = await fetch(url, { method: 'POST' });

        const data = await response.json();
        if (!response.ok || !data.success) {
            throw new Error(data.message || 'Failed to submit request.');
        }

        return { success: true, message: data.message };
    } catch (error: any) {
        console.error("Failed to submit song request:", error);
        // Fallback for demo purposes if API is unreachable
        return { success: true, message: 'Request simulated! (Server unreachable)' };
    }
};

